/*
 * Focused semantic harness for CVE-2021-47064 backport.
 *
 * It does two things:
 *  1. Reads the patched drivers/net/wireless/mediatek/mt76/dma.c (path passed
 *     as argv[1]) and asserts that mt76_dma_tx_queue_skb_raw now declares
 *     "struct mt76_queue_buf buf = {};" (zero initializer).
 *  2. Replays the mt76_dma_add_buf / mt76_dma_tx_cleanup_idx skip_unmap logic
 *     with a struct identical to struct mt76_queue_buf:
 *       positive path: zero-initialized buf -> skip_buf0 false -> unmap called
 *       negative path: garbage buf (skip_unmap != 0) -> skip_buf0 true -> unmap
 *                      skipped (the DMA mapping leak)
 *
 * Exit code 0 only if every assertion holds.
 */
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct mt76_queue_buf {
	unsigned long addr;
	unsigned short len;
	bool skip_unmap;
};

struct mt76_queue_entry {
	bool skip_buf0;
	bool skip_buf1;
};

static int unmap_calls;

static void add_buf(struct mt76_queue_buf *buf, int nbufs,
		    struct mt76_queue_entry *entry)
{
	/* mirrors mt76_dma_add_buf for the nbufs == 1 raw-tx case */
	for (int i = 0; i < nbufs; i += 2, buf += 2) {
		if (buf[0].skip_unmap)
			entry->skip_buf0 = true;
		entry->skip_buf1 = (i == nbufs - 1);
	}
}

static void cleanup(struct mt76_queue_entry *e)
{
	/* mirrors mt76_dma_tx_cleanup_idx buffer-0 unmap decision */
	if (!e->skip_buf0)
		unmap_calls++;
}

static int check_declaration(const char *path)
{
	FILE *f = fopen(path, "r");
	char line[512];
	int infunc = 0, found_zero = 0, found_uninit = 0, lineno = 0;

	if (!f) {
		perror("fopen");
		return -1;
	}
	while (fgets(line, sizeof(line), f)) {
		lineno++;
		if (strstr(line, "mt76_dma_tx_queue_skb_raw(struct"))
			infunc = 1;
		if (infunc && strstr(line, "struct mt76_queue_buf buf = {};")) {
			found_zero = 1;
			infunc = 2;
		}
		if (infunc == 1 && strstr(line, "struct mt76_queue_buf buf;"))
			found_uninit = 1;
	}
	fclose(f);
	printf("declaration check: found `buf = {}`=%d, found uninitialized `buf;`=%d (line %d)\n",
	       found_zero, found_uninit, lineno);
	return (found_zero && !found_uninit) ? 0 : -1;
}

int main(int argc, char **argv)
{
	if (argc != 2) {
		fprintf(stderr, "usage: %s <path-to-dma.c>\n", argv[0]);
		return 2;
	}

	if (check_declaration(argv[1]) != 0) {
		fprintf(stderr, "FAIL: patched declaration not found\n");
		return 1;
	}

	/* positive path: the fix zero-initializes buf */
	{
		struct mt76_queue_buf buf = {};
		struct mt76_queue_entry e = {};

		buf.addr = 0xdead0000UL;
		buf.len = 128;
		add_buf(&buf, 1, &e);
		unmap_calls = 0;
		cleanup(&e);
		if (e.skip_buf0 || unmap_calls != 1) {
			fprintf(stderr, "FAIL positive: skip_buf0=%d unmap=%d\n",
				e.skip_buf0, unmap_calls);
			return 1;
		}
		printf("positive path PASS: zero-initialized buf -> skip_buf0=false -> unmap called\n");
	}

	/* negative path: emulate stack garbage at the skip_unmap offset */
	{
		struct mt76_queue_buf buf;
		struct mt76_queue_entry e = {};

		memset(&buf, 0xff, sizeof(buf));
		buf.addr = 0xdead0000UL;
		buf.len = 128;
		add_buf(&buf, 1, &e);
		unmap_calls = 0;
		cleanup(&e);
		if (!e.skip_buf0 || unmap_calls != 0) {
			fprintf(stderr, "FAIL negative: leak condition not reproduced\n");
			return 1;
		}
		printf("negative path PASS: garbage skip_unmap -> skip_buf0=true -> unmap leaked (bug condition)\n");
	}

	printf("ALL CHECKS PASSED\n");
	return 0;
}

